def find_chain(tokens):
    tokens = list(tokens)
    n = len(tokens)
    for i in range(n):
        for j in range(i + 1, n):
            if tokens[i] == tokens[j]:
                break
        else:
            break
        if i == j:
            break
    return tokens[i:j+1]

